/* Asistente IA: usa Claude si el visor lo permite; si no, responde con reglas básicas */
let hist=[];
const aiW=()=>{if(!hist.length){$("#aiM").innerHTML="";aiAdd("a",t("ai_w"))}$("#aiC").innerHTML=["ai_c0","ai_c1","ai_c2"].map(k=>`<button class="filter" data-aq="${k}">${t(k)}</button>`).join("")};
function aiAdd(r,txt){const d=document.createElement("div");d.className="msg "+r;aiLink(d,txt);$("#aiM").appendChild(d);$("#aiM").scrollTop=1e9;return d}
function aiLink(d,txt){d.textContent="";txt.split(/(https:\/\/www\.google\.com\/maps\/[^\s)]+)/).forEach(s=>{if(s.startsWith("https://www.google.com/maps/")){const a=document.createElement("a");a.href=s;a.target="_blank";a.rel="noopener";a.textContent="Google Maps ↗";d.appendChild(a)}else d.appendChild(document.createTextNode(s))})}
const CTX=()=>`You are the REEVA site assistant (circular/upcycled fashion marketplace in Panama). Reply briefly in the user's language. Site: Home, Shop (filters: women/men/unisex and clothing/bags/accessories; each garment has a Story Tag), Community (reels, join as buyer or designer; designers need REEVA approval before selling), Impact (UNEP and UN-Habitat: 92 million tonnes of textile waste per year, a truckload of clothes burned or landfilled every second), Drop-off centers (map of Panama with Google Maps links), About REEVA (team, story). Pieces have sizes with demo stock; the heart saves favorites (My favorites panel); the profile menu has dark mode, settings, help and contact. Payments are demo only: planned methods are Yappy, card, ACH transfer, cash on pickup. Drop-off centers (fictional demo): ${Z.map(z=>`${z[0]} in ${z[2]}, ${z[1]} accepts ${z[5].map(m=>T.en["m"+m]).join("/")} -> directions https://www.google.com/maps/dir/?api=1&destination=${z[4]},${z[3]}`).join("; ")}. For transport questions, recommend the nearest center and give its directions link exactly as above; don't invent bus routes, schedules or prices. If you don't know, say so.`;
async function aiSend(m){m=(m||"").trim();if(!m)return;$("#aiQ").value="";aiAdd("u",m);const out=aiAdd("a",t("ai_th"));hist.push({role:"user",content:m});
try{const s=await claude.use("sample");if(!s)throw 0;const r=await s([{role:"user",content:CTX()+"\n\nConversation:\n"+hist.map(h=>h.role+": "+h.content).join("\n")+"\nassistant:"}],{cache:false,modelTier:"quick",onText:({text})=>aiLink(out,text)});aiLink(out,r.text);hist.push({role:"assistant",content:r.text})}
catch(err){const q=m.toLowerCase();let z=Z.find(z=>q.includes(z[2].toLowerCase())||q.includes(z[1].toLowerCase()))||Z[0];const r=(/yappy|pag|pay/.test(q)?t("pay_t")+": Yappy · "+t("pay_c")+" · ACH · "+t("pay_e"):t("ai_fb").replace("{n}",z[0]).replace("{p}",z[2]+", "+z[1])+" "+dirU(z));aiLink(out,r);hist.push({role:"assistant",content:r})}}
$("#ai").onclick=()=>{$("#aiP").classList.toggle("on")};document.addEventListener("click",e=>{const x=e.target.closest("[data-aq]");if(x)aiSend(t(x.dataset.aq))});
