/* Soporte específico para dashboard.html */
function dashInit(){
  const dAcc=$("#dash-acc"), dFav=$("#dash-fav"), dBag=$("#dash-bag");
  if(!dAcc && !dFav && !dBag) return;
  if($("#dash-fav-count")) $("#dash-fav-count").textContent = fav.size;
  if($("#dash-bag-count")) $("#dash-bag-count").textContent = cart.reduce((a,c)=>a+c.q,0);
  if($("#dash-role-stat")) $("#dash-role-stat").textContent = acct ? (acct.role==="d" ? (acct.ok ? t("rl_dok") : t("rl_dpend")) : t("ac_buyer")) : "Invitado";
  if(dFav){
    const a=[...fav].filter(i=>P[i]);
    dFav.innerHTML = a.length ? a.map(i=>{const p=P[i];return `<div class="fi">${im(p[6],p[7])}<div><b>${esc(p[0])}</b><small class="note">$${p[4].toFixed(2)} · ${esc(who(p))}</small></div><button class="button b-blue" style="padding:9px 12px" data-a="${i}">${t("pick")}</button><button class="icon-btn" data-f="${i}" aria-label="♥" style="color:var(--red)">♥</button></div>`}).join("") : `<p class="lead">${t("fav_e")}</p><a class="button b-red" href="index.html#tienda">${t("h_c1")}</a>`;
  }
  if(dBag){
    dBag.innerHTML = cart.length ? cart.map((c,k)=>`<div class="cr"><span>${esc(P[c.i][0])}<br><small class="note">${t("size")}: ${szl(c.s)} · ×${c.q}</small></span><b>$${(P[c.i][4]*c.q).toFixed(2)}</b><button data-r="${k}">${t("rm")}</button></div>`).join("") + `<p class="cr"><span>${t("sub")}</span><b>$${cartTot().toFixed(2)}</b></p>` : `<p class="note">${t("empty")}</p>`;
  }
  if(dAcc){
    dAcc.innerHTML = $("#accB") ? $("#accB").innerHTML : "";
  }
}
const _origI18n = i18n;
i18n = function(){ _origI18n(); dashInit(); };
const _origFavSync = favSync;
favSync = function(){ _origFavSync(); dashInit(); };
const _origCart = cart_;
cart_ = function(){ _origCart(); dashInit(); };
const _origAccR = accR;
accR = function(){ _origAccR(); dashInit(); };
dashInit();
